export interface FactoryIssueRow {
  readonly issue: number;
  readonly title: string;
  readonly url?: string;
  /** The latest run of each stage that has run, in pipeline order. */
  readonly stages: readonly FactoryStageRun[];
  /** weave's recorded cost across every run of every stage. */
  readonly usd: number;
  /** hexa's, across the same runs — its child processes' inference, the frontier's dollars among it. */
  readonly hexaUsd: number;
  /** The most recently settled stage's `NEXT:` line — absent when that stage named none. */
  readonly next?: string;
  /** The issue's most recent run, whatever its stage — what the supervisor judges (factory-watch.ts). */
  readonly latest?: { readonly stage: FactoryStage; readonly taskId: string; readonly state: StageState; readonly next?: string; readonly ts: number; readonly at?: number };
  /** Every run of every stage, by how it stands — the issue's status at a glance ("13 runs: 11 done, 1 failed, 1 open"). */
  readonly runs?: { readonly total: number; readonly done: number; readonly failed: number; readonly open: number; readonly cancelled: number };
  /** The issue's pull request and its CI verdict, as the supervisor last read it from the forge (`factory.ci`). */
  readonly pr?: {
    readonly number: number; readonly url: string; readonly sha: string; readonly ci: "success" | "failure" | "pending"; readonly failing: readonly string[]; readonly ts: number;
    /** Whether it is open, merged or closed without merging, as the supervisor last read it (`factory.pr`, ADR-0132
     *  amended 2026-10-09) — absent until read; a `factory.ci` for a new number starts it unread again. */
    readonly state?: "open" | "merged" | "closed";
    /** When that state was recorded. */
    readonly stateTs?: number;
  };
  /** Every pull request of this issue recorded closed without merging, in the order they closed. */
  readonly closedPrs?: readonly number[];
  /** The merger's last decision on this issue's pull request (`factory.merge`): merged, or held and why. */
  readonly merge?: { readonly sha: string; readonly merged: boolean; readonly reasons: readonly string[]; readonly ts: number };
  /** What the merge gate traces (ADR-0196 §8.2): the accepted triage / intent / plan attempts and the PR's head —
   *  from the log's raw rows and every snapshot's `factory` block, so compaction never loses it. */
  readonly provenance?: SnapshotProvenance;
  /** Its latest review's standing (ADR-0196 §12, amended 2026-10-09 — `review-gate.ts`): "same head already reviewed:
   *  <finding>" while no work has landed since, and `handoff` once the loop is the chief's or a person's. */
  readonly reviewHold?: ReviewHold;
  /** Set once the issue closed on the forge — its pull request merged (ADR-0132, amended). The board folds it away. */
  readonly completed?: { readonly ts: number };
  /** Calls on this issue waiting for a person right now. */
  readonly waiting: number;
  /** Those calls — what an Approve or Deny acts on (the id), and what it would do (the headline). */
  readonly pending: readonly { readonly requestId: string; readonly taskId: string; readonly tool: string; readonly detail: string }[];
  readonly updatedTs: number;
}

