export type FactoryStage = "triage" | "intent" | "design" | "plan" | "build" | "verify" | "ship" | "review" | "close";

export interface FactoryStageRun {
  readonly stage: FactoryStage;
  readonly taskId: string;
  /** 1 for `f<N>-<stage>`, k for `f<N>-<stage>-<k>`. */
  readonly attempt: number;
  readonly state: StageState;
  readonly model?: string;
  /** How the stage's model was chosen, from its spec (ADR-0140): `router: …`, or `escalation: …` for a retry run one
   *  tier up after a task-caused failure (amended 2026-10-08) — then `escalatedFrom` is the model the failed run used. */
  readonly routedBy?: string;
  readonly escalatedFrom?: string;
  readonly backend?: string;
  readonly usd: number;
  /** What hexa spent inside this run's hexa tool calls (ADR-0132 slice 5); metered as a tool-tagged task.spend since ADR-0184, which `usd` skips. */
  readonly hexaUsd: number;
  /** The stage's own `NEXT:` line, when it settled with one. */
  readonly next?: string;
  /** The stamp (HLC `p`, ms) this run's state rests on — its accepted terminal's, or for an open run the newest it
   *  holds; 0 for a run known only from a snapshot's final record. The state is stable once the replica's stable
   *  horizon has passed it (ADR-0196 §4); a decision over its absence waits until then. */
  readonly at?: number;
}

