export interface HarnessFacts {
  /** `retired`: node ids that are history, not hosts (`retiredNodes`) — present only when there is one. */
  readonly hosts: { readonly up: number; readonly total: number; readonly versions: readonly string[]; readonly down: readonly string[]; readonly retired?: readonly string[] };
  readonly agents: { readonly live: number; readonly total: number };
  readonly running: number;
  readonly queued: number;
  readonly done24h: number;
  readonly failed24h: number;
  /** Present when a budget policy is known. `freesAt`: when the window goes back under the line it is over (the
   *  budget when over, else 90% of it) as its oldest spend ages out — present only while at or past 90%. */
  readonly spend?: { readonly usd: number; readonly budgetUsd: number; readonly fraction: number; readonly windowMs: number; readonly freesAt?: number };
  readonly yolo: { readonly on: boolean; readonly until?: number; readonly offSince?: number; readonly ended?: "off" | "expired" | "halt" };
  readonly chief: { readonly on: boolean; readonly why?: string; readonly actsLastHour: number };
  readonly needsYou: number;
  /** Open forge issues the factory never started; absent = unknown (no factory add-on, or not read yet). */
  readonly backlog?: number;
  /** Absent when no decision records are on disk. */
  readonly decisions?: DecisionCounts;
  /** The chief of staff's reconciler (ADR-0208 §4): whether it runs, and its last pass — when, drift found, fixed, left. */
  readonly reconcile: { readonly on: boolean; readonly why?: string; readonly lastTs?: number; readonly findings: number; readonly fixed: number; readonly left: number };
  /** Yolo's autonomy level (ADR-0209 §6): standard or full, whether full is on, and the merges in the cap's window. */
  readonly autonomy: AutonomyFact;
  /** Each host's telemetry from its newest fresh heartbeat (ADR-0211 §4) — facts only; absent when none reports. */
  readonly machines?: readonly MachineFact[];
  /** The factory's churn over 24 h (ADR-0196 §12, amended 2026-10-09): `factoryChurn`. */
  readonly churn: FactoryChurn;
  /** The Raft control plane (ADR-0216 PR 1): `off` in log mode — shown disabled, not hidden — else shadow's agreement. */
  readonly controlRaft: ControlRaftFact;
  /** Whether every peer applies the log's control plane (ADR-0212 §4) — peers reporting a digest, in sync, behind. */
  readonly controlPlane: {
    readonly peers: number; readonly inSync: number; readonly behind: readonly { readonly agent: string; readonly difference: string }[];
    /** The gateways — the declarers — beside the peers (ADR-0213 (c)); absent when none reports a digest. */
    readonly gateways?: { readonly total: number; readonly inSync: number };
  };
  /** A model setting two live gateways resolve differently, with each one's source (ADR-0213 (c)). */
  readonly modelSources?: readonly { readonly setting: string; readonly values: readonly { readonly gateway: string; readonly value: string; readonly source: string }[] }[];
  /** The peers' breaker summaries (ADR-0213 (e)); absent when no peer reports one. */
  readonly breakers?: { readonly open: number; readonly agree: boolean; readonly disagree: readonly string[] };
  /** The Control page's path (ADR-0217 §5) — Home links it in one line. */
  readonly control: string;
  /** An account at its usage limit, until when, and the lanes work fails over to (ADR-0203 amended 2026-10-10). */
  readonly usageLimit?: UsageLimitFact;
}

